const choices = document.querySelector("#choices");
const restart = document.querySelector("#restart");
const trail = document.querySelector("#trail");
let currentId = "start";
let depth = 1;

function render() {
  const scene = SCENES[currentId];
  chapter.textContent = scene.chapter;
  title.textContent = scene.title;
  text.textContent = scene.text;
  art.style.backgroundImage = `url("${scene.image}")`;
  art.setAttribute("aria-label", scene.title);
  choices.replaceChildren();
  scene.choices?.forEach((choice, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.key = String(index + 1);
    button.textContent = choice.label;
    button.addEventListener("click", () => choose(choice.next));
    choices.append(button);
  });
  restart.hidden = !scene.ending;
  trail.replaceChildren(...[1, 2, 3].map((step) => {
    const dot = document.createElement("span");
    if (step <= depth) dot.className = "done";
    return dot;
  }));
}

function choose(next) {
  currentId = next;
  depth = Math.min(3, depth + 1);
  render();
  void window.jr?.state?.set("storyProgress", { currentId, depth }).catch(() => {});
  (choices.querySelector("button") || restart).focus();
}

restart.addEventListener("click", () => {
  currentId = "start";
  depth = 1;
  render();
  void window.jr?.state?.delete("storyProgress").catch(() => {});
});
window.addEventListener("keydown", (event) => {
  const buttons = [...choices.querySelectorAll("button")];
  if (event.key === "1" || event.key === "2") buttons[Number(event.key) - 1]?.click();
  if ((event.key === "ArrowLeft" || event.key === "ArrowRight") && buttons.length) {
    event.preventDefault();
    const direction = document.documentElement.dir === "rtl" ? -1 : 1;
    const delta = event.key === "ArrowRight" ? direction : -direction;
    const index = Math.max(0, buttons.indexOf(document.activeElement));
    buttons[(index + delta + buttons.length) % buttons.length].focus();
  }
});
async function initializeStory() {
  try {
    const saved = await window.jr?.state?.get("storyProgress");
    if (saved && Object.hasOwn(SCENES, saved.currentId)) {
      currentId = saved.currentId;
      depth = Math.max(1, Math.min(3, Number(saved.depth) || 1));
    }
  } catch {}
  render();
}

void initializeStory();

