// ⭐ CHANGE THESE
const colors = ["#ef4444", "#f97316", "#facc15", "#22c55e", "#38bdf8", "#8b5cf6", "#111827"];
const brushSizes = [6, 12, 22];
const stamps = ["⭐", "🌈", "💖", "🐱"];

const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");
const toolbar = document.getElementById("toolbar");
const canvasSurface = readThemeToken("--jr-surface");
let color = colors[0];
let size = brushSizes[1];
let stamp = "";
let drawing = false;
let last = null;
let activeStroke = null;
let drawingState = { base: "sample", actions: [] };
const history = [];

buildToolbar();

canvas.addEventListener("pointerdown", (event) => {
  saveSnapshot();
  drawing = true;
  const point = pointerPoint(event);
  if (stamp) {
    const action = { type: "stamp", stamp, size, x: Math.round(point.x), y: Math.round(point.y) };
    drawingState.actions.push(action);
    drawAction(action);
    drawing = false;
    saveDrawing();
    return;
  }
  last = point;
  activeStroke = { type: "stroke", color, size, points: [[Math.round(point.x), Math.round(point.y)]] };
});
canvas.addEventListener("pointermove", (event) => {
  if (!drawing || stamp) return;
  const point = pointerPoint(event);
  if (Math.hypot(point.x - last.x, point.y - last.y) < 3) return;
  drawLine(last, point, color, size);
  const savedPoint = [Math.round(point.x), Math.round(point.y)];
  if (activeStroke.points.length < 200) activeStroke.points.push(savedPoint);
  else activeStroke.points[activeStroke.points.length - 1] = savedPoint;
  last = point;
});
window.addEventListener("pointerup", finishStroke);

function finishStroke() {
  if (drawing && activeStroke) {
    if (activeStroke.points.length === 1) drawAction(activeStroke);
    drawingState.actions.push(activeStroke);
    saveDrawing();
  }
  drawing = false;
  last = null;
  activeStroke = null;
}

function pointerPoint(event) {
  const rect = canvas.getBoundingClientRect();
  return {
    x: ((event.clientX - rect.left) / rect.width) * canvas.width,
    y: ((event.clientY - rect.top) / rect.height) * canvas.height
  };
}

function buildToolbar() {
  colors.forEach((nextColor) => {
    const button = document.createElement("button");
    button.type = "button";
    button.title = nextColor;
    button.style.background = nextColor;
    button.addEventListener("click", () => {
      color = nextColor;
      stamp = "";
      markSelected(button);
    });
    toolbar.append(button);
  });
  brushSizes.forEach((nextSize) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = `${nextSize}`;
    button.addEventListener("click", () => {
      size = nextSize;
      stamp = "";
      markSelected(button);
    });
    toolbar.append(button);
  });
  stamps.forEach((nextStamp) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = nextStamp;
    button.addEventListener("click", () => {
      stamp = nextStamp;
      markSelected(button);
    });
    toolbar.append(button);
  });
  const eraser = document.createElement("button");
  eraser.type = "button";
  eraser.textContent = "Erase";
  eraser.addEventListener("click", () => {
    color = canvasSurface;
    stamp = "";
    markSelected(eraser);
  });
  toolbar.append(eraser);
  const undo = document.createElement("button");
  undo.type = "button";
  undo.textContent = "Undo";
  undo.addEventListener("click", () => {
    const snapshot = history.pop();
    if (snapshot) {
      drawingState = snapshot;
      renderDrawingState();
      saveDrawing();
    }
  });
  toolbar.append(undo);
  const clear = document.createElement("button");
  clear.type = "button";
  clear.textContent = "Clear";
  clear.addEventListener("click", () => {
    saveSnapshot();
    drawingState = { base: "blank", actions: [] };
    renderDrawingState();
    saveDrawing();
  });
  toolbar.append(clear);
}

function saveSnapshot() {
  history.push(cloneDrawingState());
  if (history.length > 20) history.shift();
}

function cloneDrawingState(state = drawingState) {
  return {
    base: state.base,
    actions: state.actions.map((action) => action.type === "stroke"
      ? { ...action, points: action.points.map((point) => [...point]) }
      : { ...action })
  };
}

function saveDrawing() {
  const saved = { version: 1, ...cloneDrawingState() };
  while (new TextEncoder().encode(JSON.stringify(saved)).length > 14500 && saved.actions.length) saved.actions.shift();
  void window.jr?.state?.set("drawing", saved).catch(() => {});
}

function drawLine(from, to, strokeColor, strokeSize) {
  ctx.strokeStyle = strokeColor;
  ctx.lineWidth = strokeSize;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(from.x ?? from[0], from.y ?? from[1]);
  ctx.lineTo(to.x ?? to[0], to.y ?? to[1]);
  ctx.stroke();
}

function drawAction(action) {
  if (action.type === "stamp") {
    ctx.font = `${action.size * 2.6}px system-ui`;
    ctx.textAlign = "center";
    ctx.fillText(action.stamp, action.x, action.y);
    return;
  }
  if (action.points.length === 1) {
    ctx.fillStyle = action.color;
    ctx.beginPath();
    ctx.arc(action.points[0][0], action.points[0][1], action.size / 2, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  for (let index = 1; index < action.points.length; index += 1) {
    drawLine(action.points[index - 1], action.points[index], action.color, action.size);
  }
}

function renderDrawingState() {
  clearCanvas();
  if (drawingState.base === "sample") drawSample();
  drawingState.actions.forEach(drawAction);
}

function validPoint(point) {
  return Array.isArray(point) && point.length === 2 && point.every(Number.isFinite);
}

function validAction(action) {
  if (!action || !brushSizes.includes(action.size)) return false;
  if (action.type === "stamp") return stamps.includes(action.stamp) && Number.isFinite(action.x) && Number.isFinite(action.y);
  return action.type === "stroke" && typeof action.color === "string" && action.color.length <= 32 && Array.isArray(action.points) && action.points.length > 0 && action.points.length <= 200 && action.points.every(validPoint);
}

async function initializeDrawing() {
  try {
    const saved = await window.jr?.state?.get("drawing");
    if (saved?.version === 1 && ["sample", "blank"].includes(saved.base) && Array.isArray(saved.actions) && saved.actions.length <= 100 && saved.actions.every(validAction)) {
      drawingState = cloneDrawingState(saved);
    }
  } catch {}
  renderDrawingState();
}

function drawSample() {
  ctx.strokeStyle = colors[4];
  ctx.lineWidth = 18;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(150, 420);
  ctx.quadraticCurveTo(350, 130, 540, 350);
  ctx.quadraticCurveTo(680, 500, 830, 230);
  ctx.stroke();
  ctx.font = "88px system-ui";
  ctx.textAlign = "center";
  ctx.fillText("🌈  ⭐", 500, 250);
}

function clearCanvas() {
  ctx.fillStyle = canvasSurface;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

function readThemeToken(token) {
  return getComputedStyle(document.documentElement).getPropertyValue(token).trim();
}

function markSelected(button) {
  toolbar.querySelectorAll("button").forEach((item) => item.classList.remove("selected"));
  button.classList.add("selected");
}

void initializeDrawing();

