const themes = [
  { name: "Birthday", label: "Birthday sparkle", background: "var(--jr-surface)", accent: "var(--jr-accent)", confetti: ["🎉", "✨", "🎂"] },
  { name: "Thanks", label: "Big thanks", background: "linear-gradient(135deg, var(--jr-surface), var(--jr-bg))", accent: "var(--jr-accent)", confetti: ["🌸", "💚", "✨"] },
  { name: "Holiday", label: "Holiday cheer", background: "linear-gradient(135deg, var(--jr-bg), var(--jr-surface))", accent: "var(--jr-surface-text)", confetti: ["❄️", "⭐", "🎁"] }
];
const messages = [
  "You make ordinary days feel like a party.",
  "Sending a pocket-sized celebration your way.",
  "Here is a tiny card with a very big smile inside."
];

const card = document.getElementById("card");
const themeLabel = document.getElementById("theme");
const message = document.getElementById("message");
const flip = document.getElementById("flip");
const themesEl = document.getElementById("themes");
const confetti = document.getElementById("confetti");
let messageIndex = 0;
let themeIndex = 0;

flip.addEventListener("click", () => {
  messageIndex = (messageIndex + 1) % messages.length;
  card.classList.remove("flip");
  void card.offsetWidth;
  card.classList.add("flip");
  setTimeout(() => {
    message.textContent = messages[messageIndex];
    burst();
  }, 260);
});

themes.forEach((theme, index) => {
  const button = document.createElement("button");
  button.type = "button";
  button.textContent = theme.name;
  button.addEventListener("click", () => {
    themeIndex = index;
    applyTheme();
    burst();
  });
  themesEl.append(button);
});

function applyTheme() {
  const theme = themes[themeIndex];
  themeLabel.textContent = theme.label;
  card.style.background = theme.background;
  themeLabel.style.color = theme.accent;
}

function burst() {
  const theme = themes[themeIndex];
  for (let i = 0; i < 24; i++) {
    const piece = document.createElement("span");
    piece.textContent = theme.confetti[i % theme.confetti.length];
    piece.style.left = `${Math.random() * 100}vw`;
    piece.style.animationDelay = `${Math.random() * 0.35}s`;
    confetti.append(piece);
    setTimeout(() => piece.remove(), 3100);
  }
}

applyTheme();
burst();

