const GRID_SIZE = 12;
const COLORS = ["#ffffff", "#172033", "#ef476f", "#ff9f1c", "#ffd166", "#06d6a0", "#118ab2", "#7b2cbf"];
const START_PIXELS = [40,41,42,43,51,52,53,54,63,64,65,66,75,78,87,90,100,101,102,103];

const grid = document.querySelector("#grid");
const palette = document.querySelector("#palette");
const framesElement = document.querySelector("#frames");
const fps = document.querySelector("#fps");
const fpsValue = document.querySelector("#fps-value");
let frames = [Array(GRID_SIZE * GRID_SIZE).fill(COLORS[0])];
START_PIXELS.forEach((pixel) => frames[0][pixel] = COLORS[5]);
let frameIndex = 0;
let color = COLORS[2];
let tool = "pencil";
let drawing = false;
let cursor = 0;
let timer;
let drawingChanged = false;

function savePixelArt() {
  void window.jr?.state?.set("pixelArt", {
    frames: frames.map((frame) => frame.map((pixelColor) => COLORS.indexOf(pixelColor)).join("")),
    frameIndex,
    colorIndex: COLORS.indexOf(color),
    tool,
    fps: Number(fps.value)
  }).catch(() => {});
}

function paintPixel(index) {
  const frame = frames[frameIndex];
  if (tool === "fill") flood(index, frame[index], color);
  else frame[index] = tool === "eraser" ? COLORS[0] : color;
  drawingChanged = true; renderGrid(); renderFrames();
}
function flood(start, target, replacement) {
  if (target === replacement) return;
  const frame = frames[frameIndex]; const queue = [start];
  while (queue.length) {
    const index = queue.pop(); if (frame[index] !== target) continue; frame[index] = replacement;
    const x = index % GRID_SIZE; const y = Math.floor(index / GRID_SIZE);
    if (x) queue.push(index - 1); if (x < GRID_SIZE - 1) queue.push(index + 1); if (y) queue.push(index - GRID_SIZE); if (y < GRID_SIZE - 1) queue.push(index + GRID_SIZE);
  }
}
function renderGrid() {
  grid.replaceChildren(...frames[frameIndex].map((pixelColor, index) => {
    const pixel = document.createElement("button"); pixel.type = "button"; pixel.className = `pixel${cursor === index ? " cursor" : ""}`; pixel.style.background = pixelColor; pixel.setAttribute("role", "gridcell"); pixel.setAttribute("aria-label", `Pixel ${index + 1}`);
    pixel.addEventListener("pointerdown", (event) => { drawing = true; cursor = index; event.currentTarget.setPointerCapture(event.pointerId); paintPixel(index); });
    pixel.addEventListener("pointerenter", () => { if (drawing && tool !== "fill") { cursor = index; paintPixel(index); } });
    pixel.addEventListener("pointerup", finishDrawing);
    return pixel;
  }));
}
function renderFrames() {
  framesElement.replaceChildren(...frames.map((frame, index) => {
    const button = document.createElement("button"); button.type = "button"; button.className = `frame${index === frameIndex ? " active" : ""}`; button.setAttribute("aria-label", `Frame ${index + 1}`);
    button.append(...frame.map((pixelColor) => { const dot = document.createElement("span"); dot.style.background = pixelColor; return dot; }));
    button.addEventListener("click", () => { frameIndex = index; renderGrid(); renderFrames(); savePixelArt(); }); return button;
  }));
}
COLORS.forEach((swatchColor, index) => { const button = document.createElement("button"); button.type = "button"; button.className = `swatch${swatchColor === color ? " active" : ""}`; button.style.background = swatchColor; button.setAttribute("aria-label", `Color ${index + 1}`); button.addEventListener("click", () => { color = swatchColor; document.querySelectorAll(".swatch").forEach((item) => item.classList.remove("active")); button.classList.add("active"); savePixelArt(); }); palette.append(button); });
document.querySelector("#tools").addEventListener("click", (event) => { const button = event.target.closest("button"); if (!button) return; tool = button.dataset.tool; document.querySelectorAll("#tools button").forEach((item) => item.classList.toggle("active", item === button)); savePixelArt(); });
document.querySelector("#add").addEventListener("click", () => { if (frames.length >= 48) return; frames.push(Array(GRID_SIZE * GRID_SIZE).fill(COLORS[0])); frameIndex = frames.length - 1; renderGrid(); renderFrames(); savePixelArt(); });
document.querySelector("#duplicate").addEventListener("click", () => { if (frames.length >= 48) return; frames.splice(frameIndex + 1, 0, [...frames[frameIndex]]); frameIndex += 1; renderGrid(); renderFrames(); savePixelArt(); });
document.querySelector("#delete").addEventListener("click", () => { if (frames.length === 1) frames[0].fill(COLORS[0]); else frames.splice(frameIndex, 1); frameIndex = Math.min(frameIndex, frames.length - 1); renderGrid(); renderFrames(); savePixelArt(); });
document.querySelector("#play").addEventListener("click", (event) => { if (timer) { clearInterval(timer); timer = undefined; event.currentTarget.textContent = "▶ Play"; return; } event.currentTarget.textContent = "■ Stop"; timer = setInterval(() => { frameIndex = (frameIndex + 1) % frames.length; renderGrid(); renderFrames(); }, 1000 / Number(fps.value)); });
fps.addEventListener("input", () => fpsValue.textContent = `${fps.value} FPS`);
fps.addEventListener("change", savePixelArt);
function finishDrawing() { drawing = false; if (drawingChanged) { drawingChanged = false; savePixelArt(); } }
window.addEventListener("pointerup", finishDrawing);
window.addEventListener("keydown", (event) => { let next = cursor; if (event.key === "ArrowLeft") next -= 1; if (event.key === "ArrowRight") next += 1; if (event.key === "ArrowUp") next -= GRID_SIZE; if (event.key === "ArrowDown") next += GRID_SIZE; if (next !== cursor) { event.preventDefault(); cursor = Math.max(0, Math.min(frames[0].length - 1, next)); renderGrid(); grid.children[cursor].focus(); } if (event.code === "Space" && document.activeElement?.classList.contains("pixel")) { event.preventDefault(); paintPixel(cursor); finishDrawing(); } });

async function initializePixelArt() {
  fps.value = "6";
  try {
    const saved = await window.jr?.state?.get("pixelArt");
    const savedFrames = saved?.frames;
    if (Array.isArray(savedFrames) && savedFrames.length > 0 && savedFrames.length <= 48 && savedFrames.every((frame) => typeof frame === "string" && /^[0-7]{144}$/.test(frame))) {
      frames = savedFrames.map((frame) => [...frame].map((pixel) => COLORS[Number(pixel)]));
      frameIndex = Math.max(0, Math.min(frames.length - 1, Number(saved.frameIndex) || 0));
      if (Number.isInteger(saved.colorIndex) && COLORS[saved.colorIndex]) color = COLORS[saved.colorIndex];
      if (["pencil", "eraser", "fill"].includes(saved.tool)) tool = saved.tool;
      if (Number.isFinite(saved.fps) && saved.fps >= 1 && saved.fps <= 12) fps.value = String(saved.fps);
    }
  } catch {}
  document.querySelectorAll(".swatch").forEach((item, index) => item.classList.toggle("active", COLORS[index] === color));
  document.querySelectorAll("#tools button").forEach((item) => item.classList.toggle("active", item.dataset.tool === tool));
  renderGrid(); renderFrames(); fps.dispatchEvent(new Event("input"));
}

void initializePixelArt();

