];

const recipesEl = document.getElementById("recipes");
const detail = document.getElementById("detail");
const search = document.getElementById("search");
let selected = 0;

function renderCards() {
  recipesEl.innerHTML = "";
  const query = search.value.trim().toLowerCase();
  recipes.forEach((recipe, index) => {
    if (query && ![recipe.name, ...recipe.ingredients].join(" ").toLowerCase().includes(query)) return;
    const button = document.createElement("button");
    button.type = "button";
    button.className = index === selected ? "recipe-card selected" : "recipe-card";
    button.style.animationDelay = `${index * 90}ms`;
    button.innerHTML = `<span>${recipe.emoji}</span><div><h2>${recipe.name}</h2><p>${recipe.time}</p></div>`;
    button.addEventListener("click", () => {
      selected = index;
      render();
    });
    recipesEl.append(button);
  });
}

function renderDetail() {
  const recipe = recipes[selected];
  detail.innerHTML = `
    <h2>${recipe.emoji} ${recipe.name}</h2>
    <p class="meta">${recipe.time}</p>
    <div class="columns">
      <div>
        <h3>Ingredients</h3>
        ${recipe.ingredients.map((item) => `<label><input type="checkbox" /> ${item}</label>`).join("")}
      </div>
      <div>
        <h3>Steps</h3>
        <ol>${recipe.steps.map((step) => `<li>${step}</li>`).join("")}</ol>
      </div>
    </div>
  `;
}

function render() {
  renderCards();
  renderDetail();
}

search.addEventListener("input", () => {
  const query = search.value.trim().toLowerCase();
  const first = recipes.findIndex((recipe) => [recipe.name, ...recipe.ingredients].join(" ").toLowerCase().includes(query));
  if (first >= 0) selected = first;
  render();
});
render();

