// ⭐ CHANGE THESE
const PET_NAME = "Mochi";
const GOAL_MOMENTS = 6;
const STARTING_NEEDS = { joy: 64, energy: 72, hunger: 58 };
const ACTIONS = {
  feed: { joy: 4, energy: 3, hunger: 24, reaction: "Crunch! Delicious.", mood: "That snack hit the spot." },
  play: { joy: 22, energy: -14, hunger: -8, reaction: "Wheee!", mood: "Best playtime ever!" },
  rest: { joy: 3, energy: 25, hunger: -5, reaction: "Zzz...", mood: "A tiny nap feels wonderful." }
};

const state = { ...STARTING_NEEDS, moments: 0 };
const images = {
  happy: { src: "assets/pet-happy.png", alt: "happy virtual pet" },
  hungry: { src: "assets/pet-hungry.png", alt: "hungry virtual pet" },
  sleepy: { src: "assets/pet-sleepy.png", alt: "sleepy virtual pet" },
  excited: { src: "assets/pet-excited.png", alt: "excited virtual pet" }
};
const pet = document.querySelector("#pet");
const reaction = document.querySelector("#reaction");
const mood = document.querySelector("#mood");
document.querySelector("#pet-name").textContent = PET_NAME;

void initializePet();

async function initializePet() {
  try {
    const saved = await window.jr?.state?.get("pet");
    if (saved && typeof saved === "object") {
      for (const key of ["joy", "energy", "hunger", "moments"]) {
        if (Number.isFinite(saved[key]) && saved[key] >= 0) state[key] = saved[key];
      }
    }
  } catch {
    // The exported project still works when Jr. project data is unavailable.
  }
  render();
}

function savePet() {
  const request = window.jr?.state?.set("pet", { ...state });
  if (request) void request.catch(() => undefined);
}

function clamp(value) { return Math.max(0, Math.min(100, value)); }
function render() {
  ["joy", "energy", "hunger"].forEach((need) => document.querySelector(`#${need}`).value = state[need]);
  document.querySelector("#goal").textContent = `Goal: ${state.moments} / ${GOAL_MOMENTS} happy moments`;
  let face = "happy";
  if (state.energy < 32) face = "sleepy"; else if (state.hunger < 32) face = "hungry"; else if (state.joy > 82) face = "excited";
  pet.src = images[face].src; pet.alt = images[face].alt;
  if (state.moments >= GOAL_MOMENTS) { reaction.textContent = "Goal complete! 🎉"; mood.textContent = `${PET_NAME} had a wonderfully balanced day.`; pet.src = images.excited.src; pet.alt = images.excited.alt; }
}
document.querySelectorAll("[data-action]").forEach((button) => button.addEventListener("click", () => {
  const action = ACTIONS[button.dataset.action];
  state.joy = clamp(state.joy + action.joy); state.energy = clamp(state.energy + action.energy); state.hunger = clamp(state.hunger + action.hunger); state.moments += 1;
  reaction.textContent = action.reaction; mood.textContent = action.mood; render(); savePet();
}));
setInterval(() => { if (state.moments >= GOAL_MOMENTS) return; state.joy = clamp(state.joy - 1); state.energy = clamp(state.energy - 1); state.hunger = clamp(state.hunger - 2); render(); }, 5000);

/* jr-theme-tokens-v2 */
:root { --jr-bg: #d9f2f1; --jr-bg-text: #173b3a; --jr-surface: #fffaf3; --jr-surface-text: #34271d; --jr-accent: #a8325f; --jr-accent-contrast: #ffffff; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; background: linear-gradient(180deg, var(--jr-bg), color-mix(in srgb, var(--jr-bg) 70%, #ffffff)); color: var(--jr-bg-text); font-family: ui-rounded, system-ui, sans-serif; }
main { width: min(940px, 100%); margin-inline: auto; padding: clamp(20px, 5vw, 52px); }
header { display: flex; justify-content: space-between; align-items: end; gap: 20px; margin-block-end: 20px; } header p, h1 { margin: 0; } header p { color: var(--jr-accent); font-weight: 900; text-transform: uppercase; letter-spacing: .1em; } h1 { font-size: clamp(2.3rem, 7vw, 4.8rem); line-height: .9; }
.goal { max-width: 210px; border: 2px solid var(--jr-bg-text); border-radius: 99px; padding: 10px 16px; font-weight: 900; text-align: center; }
.room { min-height: 530px; display: grid; grid-template-columns: 1.2fr .8fr; overflow: hidden; background: var(--jr-surface); color: var(--jr-surface-text); border: 4px solid var(--jr-surface-text); border-radius: 34px; box-shadow: 10px 10px 0 color-mix(in srgb, var(--jr-accent) 40%, transparent); }
.pet-stage { position: relative; display: grid; place-items: center; min-height: 400px; background: radial-gradient(circle at 50% 72%, #f4d6a0 0 18%, transparent 19%), linear-gradient(#b9e5ee 0 64%, #acd58e 64%); }
#pet { width: min(76%, 390px); height: 390px; object-fit: contain; filter: drop-shadow(0 16px 5px rgba(31,38,26,.2)); animation: breathe 2.2s ease-in-out infinite; }
.reaction { position: absolute; inset-block-start: 30px; inset-inline-end: 30px; z-index: 1; padding: 10px 15px; border-radius: 16px 16px 4px 16px; background: var(--jr-surface); color: var(--jr-surface-text); font-weight: 900; }
.care-panel { padding: clamp(24px, 5vw, 48px); display: flex; flex-direction: column; justify-content: center; }
h2 { margin: 0; font-size: 2.4rem; } #mood { line-height: 1.5; min-height: 48px; }
.meters { display: grid; gap: 14px; margin-block: 18px 26px; }.meters label { display: grid; gap: 6px; font-weight: 900; } meter { width: 100%; height: 20px; accent-color: var(--jr-accent); }
.actions { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }.actions button { border: 0; border-radius: 14px; padding: 14px 8px; background: var(--jr-accent); color: var(--jr-accent-contrast); font-family: inherit; font-size: .94rem; font-weight: 900; cursor: pointer; }.actions button:active { transform: scale(.96); }
button:focus-visible { outline: 4px solid var(--jr-surface-text); outline-offset: 3px; }.session-note { text-align: center; font-weight: 800; opacity: .72; }
@keyframes breathe { 50% { transform: translateY(-8px) rotate(1deg); } }
@media (max-width: 700px) { header { align-items: start; } .room { grid-template-columns: 1fr; } .pet-stage { min-height: 290px; } #pet { height: 270px; } .reaction { inset-block-start: 18px; inset-inline-end: 18px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; } }
